<template><div class="wrap prediction-detail page-animate"><div v-if="item" class="prediction-layout"><main class="panel prediction-main"><div class="eyebrow">Prediction analysis</div><h1>{{item.prediction}}</h1><div class="prediction-fixture"><TeamLogo :src="item.matchId?.homeTeamId?.logo" :name="item.matchId?.homeTeamId?.name" size="md"/><b>{{item.matchId?.homeTeamId?.name||item.fixture}}</b><span>vs</span><b>{{item.matchId?.awayTeamId?.name||''}}</b><TeamLogo :src="item.matchId?.awayTeamId?.logo" :name="item.matchId?.awayTeamId?.name" size="md"/></div><div class="prediction-kpis"><div><span>Odds</span><strong>{{Number(item.odds||0).toFixed(2)}}</strong></div><div><span>Confidence</span><strong>{{item.confidence||'—'}}%</strong></div><div><span>Status</span><strong>{{item.status}}</strong></div></div><h2>Why this pick?</h2><p class="analysis-copy">{{item.analysis||'No analysis was published for this prediction.'}}</p><RouterLink v-if="item.matchId?._id" :to="`/matches/${item.matchId._id}`" class="btn">Open match centre</RouterLink></main><aside class="panel"><div class="eyebrow">Tipster</div><h3>{{item.tipsterId?.name||'BraTips tipster'}}</h3><p class="muted">Review the full track record before following a prediction.</p><RouterLink to="/tipsters" class="ghost">Explore tipsters</RouterLink></aside></div><div v-else class="empty">Loading prediction…</div></div></template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import {useRoute,RouterLink} from 'vue-router';import {api} from '../services/api';import TeamLogo from '../components/TeamLogo.vue';const route=useRoute(),item=ref<any>(null);onMounted(async()=>{try{item.value=(await api.get(`/predictions/${route.params.id}`)).data}catch{item.value=null}})</script>
